// chmod(): Change mode using a pathname
const char *path = "/etc/config.file";

// Set permissions to rw-r--r-- (0644)
mode_t mode_default = 0644;

if (chmod(path, mode_default) == -1) {
    // Handle error
    return -1;
}

// Example: Set executable and sticky bit (1755)
chmod("script.sh", 01755);


// fchmod(): Change mode using a file descriptor (fd)
int fd = /* open("data.log", ...) */;

// Set permissions to rw------- (0600)
mode_t mode_private = 0600;

if (fchmod(fd, mode_private) == -1) {
    // Handle error
    return -1;
}
// close(fd);


// fchmodat(): Change mode relative to a directory fd
int dir_fd = /* open("/home/user", ...) */;
const char *rel_path = "subdir/item.txt";

// Change mode for relative path
if (fchmodat(dir_fd, rel_path, 0777, 0) == -1) {
    // Handle error
    return -1;
}

// Using AT_FDCWD for absolute path or current directory
fchmodat(AT_FDCWD, "/tmp/global.dat", 0660, 0);

// Use AT_SYMLINK_NOFOLLOW if dealing with symbolic links
fchmodat(dir_fd, "link.sym", 0644, AT_SYMLINK_NOFOLLOW);

// close(dir_fd);
